<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\ProfileExaminationCommissionAcceptanceService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:accept-profile-examination-commission',description:'Accept one exact Senator commission and assess panel readiness')]
final class SenateAcceptProfileExaminationCommissionCommand extends Command{public function __construct(private readonly ProfileExaminationCommissionAcceptanceService$s){parent::__construct();}protected function configure():void{$this->addArgument('commission-id',InputArgument::REQUIRED)->addArgument('senator-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->accept((string)$i->getArgument('commission-id'),(string)$i->getArgument('senator-binding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if($i->getOption('json'))$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));else$o->writeln('<info>PROFILE_EXAMINATION_COMMISSION_ACCEPTED</info> '.$r['acceptance']['acceptance_id']);return self::SUCCESS;}}
